def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = my[-1]
    last_op = op[-1]

    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c
    my_d = sum(1 for x in my if x == 'D')

    if op_d == n:
        return 'D'
    if n == 99:
        return 'D'

    start = n - 10
    if start < 0:
        start = 0
    recent_d = 0
    for i in range(start, n):
        if op[i] == 'D':
            recent_d += 1

    opp_streak = 0
    for x in reversed(op):
        if x == 'D':
            opp_streak += 1
        else:
            break

    punished = 0
    forgiven = 0
    after_c_d = 0
    recent_start = n - 20
    if recent_start < 0:
        recent_start = 0
    r_punished = 0
    r_forgiven = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'D':
                punished += 1
                if i >= recent_start:
                    r_punished += 1
            else:
                forgiven += 1
                if i >= recent_start:
                    r_forgiven += 1
        elif op[i + 1] == 'D':
            after_c_d += 1

    low_d = op_d <= max(2, n // 5)
    mostly_nice = op_d <= max(3, n // 4)

    if op_c == n and my_d == 0:
        if n < 98:
            return 'D'
        return 'C'

    exploit = False
    if my_d > 0 and r_forgiven > r_punished:
        if op_c == n or low_d or (r_forgiven > r_punished + 1 and recent_d <= 2):
            exploit = True
    if my_d > 0 and punished == 0 and forgiven > 0 and mostly_nice:
        exploit = True

    if not exploit and last_me == 'D' and last_op == 'C':
        if recent_d <= 1 and op_d <= max(2, n // 10) and n < 95:
            return 'C'

    if (not exploit and my_d == 1 and op_d <= 1 and recent_d == 0 and
            n >= 45 and n < 90 and last_op == 'C' and last_me == 'C'):
        return 'D'

    if exploit:
        if last_me == 'D' and last_op == 'D':
            if opp_streak >= 2 or recent_d >= 4 or op_d >= max(4, n // 3):
                return 'D'
            return 'C'
        return 'D'

    if last_op == 'D':
        if op_d >= max(2, n // 2):
            return 'D'
        if opp_streak >= 3 or recent_d >= 5:
            return 'D'
        if last_me == 'D':
            if low_d or (opp_streak <= 1 and recent_d <= 2):
                return 'C'
            return 'D'
        if low_d and recent_d <= 2 and after_c_d <= 1:
            return 'C'
        return 'D'

    if n >= 98:
        if op_d <= max(5, n // 3):
            return 'C'
        return 'D'

    if low_d:
        return 'C'
    if recent_d <= 2:
        return 'C'
    if recent_d >= 6:
        return 'D'
    if op_d <= max(5, 2 * n // 3):
        if recent_d <= 4:
            return 'C'
        return 'D'
    return 'D'
